import{_ as n,o as a,c as i,a6 as t}from"./chunks/framework.DNkVJs23.js";const c=JSON.parse('{"title":"Häufige Fragen","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://eurekaffeine.github.io/sapphire-star-codex/de/faq/"}],["meta",{"property":"og:url","content":"https://eurekaffeine.github.io/sapphire-star-codex/de/faq/"}],["meta",{"property":"og:title","content":"Häufige Fragen | Sapphire Star Codex"}],["meta",{"property":"og:description","content":"Monster-Hunter-Daten und Rüstungssuche für Wilds, Rise mit Sunbreak und World mit Iceborne."}]]},"headers":[],"relativePath":"de/faq/index.md","filePath":"de/faq/index.md"}'),r={name:"de/faq/index.md"};function s(d,e,o,l,h,u){return a(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="haufige-fragen" tabindex="-1">Häufige Fragen <a class="header-anchor" href="#haufige-fragen" aria-label="Permalink to &quot;Häufige Fragen&quot;">​</a></h1><h2 id="welche-spiele-werden-unterstutzt" tabindex="-1">Welche Spiele werden unterstützt? <a class="header-anchor" href="#welche-spiele-werden-unterstutzt" aria-label="Permalink to &quot;Welche Spiele werden unterstützt?&quot;">​</a></h2><p>Unterstützt werden Wilds, Rise mit Sunbreak und World mit Iceborne. Daten und Mechaniken bleiben nach Spiel getrennt; die Auswahl erfolgt auf der Startseite.</p><h2 id="wo-kann-ich-die-app-herunterladen" tabindex="-1">Wo kann ich die App herunterladen? <a class="header-anchor" href="#wo-kann-ich-die-app-herunterladen" aria-label="Permalink to &quot;Wo kann ich die App herunterladen?&quot;">​</a></h2><p>Android ist bei <a href="https://play.google.com/store/apps/details?id=com.eurekaffeine.mhd" target="_blank" rel="noreferrer">Google Play</a>, HarmonyOS in der <a href="https://appgallery.huawei.com/app/detail?id=com.eurekaffeine.monsterhunterdex&amp;channelId=SHARE&amp;source=appshare" target="_blank" rel="noreferrer">AppGallery</a> verfügbar. iOS wird für die Veröffentlichung vorbereitet. Unter <a href="./../#download">Download</a> findest du die aktuellen Links. Die Verfügbarkeit hängt von Region und Gerät ab.</p><h2 id="funktioniert-die-app-offline" tabindex="-1">Funktioniert die App offline? <a class="header-anchor" href="#funktioniert-die-app-offline" aria-label="Permalink to &quot;Funktioniert die App offline?&quot;">​</a></h2><p>Die Daten werden mitgeliefert. Nachschlagen, Suche, Favoriten und Rüstungssuche laufen lokal. Externe Links und Updates benötigen eine Verbindung.</p><h2 id="wie-funktioniert-die-rustungssuche" tabindex="-1">Wie funktioniert die Rüstungssuche? <a class="header-anchor" href="#wie-funktioniert-die-rustungssuche" aria-label="Permalink to &quot;Wie funktioniert die Rüstungssuche?&quot;">​</a></h2><p>Wähle Fähigkeiten und Stufen, fixiere oder schließe Ausrüstung aus und berücksichtige deine Dekorationen. Rise unterstützt eigene Talismane und augmentierte Rüstungen. Die Ergebnisse hängen von Daten und Vorgaben ab; die Suche ist kein Schadensrechner.</p><h2 id="welche-sprachen-sind-verfugbar" tabindex="-1">Welche Sprachen sind verfügbar? <a class="header-anchor" href="#welche-sprachen-sind-verfugbar" aria-label="Permalink to &quot;Welche Sprachen sind verfügbar?&quot;">​</a></h2><p>Die App bietet 14 Sprachen. Manche Spieltexte erscheinen weiterhin auf Englisch. Fehlender lateinamerikanischer spanischer Text wird zuerst durch spanischen Text aus Spanien und dann durch Englisch ersetzt.</p><p>English · 日本語 · 简体中文 · 繁體中文 · Français · Deutsch · Italiano · 한국어 · Español (España) · Español (Latinoamérica) · Português (Brasil) · Polski · Русский · العربية</p><h2 id="ist-dies-eine-offizielle-app" tabindex="-1">Ist dies eine offizielle App? <a class="header-anchor" href="#ist-dies-eine-offizielle-app" aria-label="Permalink to &quot;Ist dies eine offizielle App?&quot;">​</a></h2><p>Nein. Die unabhängige Fan-App ist weder mit CAPCOM verbunden noch von CAPCOM bestätigt. Monster-Hunter-Grafiken und Spieldaten gehören CAPCOM Co., Ltd.</p>',14)])])}const f=n(r,[["render",s]]);export{c as __pageData,f as default};
